use anyhow::Result;
use rustplotlib::*;
use serde_json::Value;
use std::fs;
fn num(v:&Value,k:&str)->f64{v[k].as_f64().unwrap_or(f64::NAN)}
fn figure(w:f64,h:f64)->Figure{let mut f=Figure::new(IntendedUse::ArticleWide);f.width_mm=w;f.height_mm=h;f.font_pt=9.;f.tight_export=false;f.check_label_bounds=false;f.check_label_overlap=false;f.check_label_geometry=false;f.latex.cache="build/flight-plot-latex".into();f}
fn label(f:&mut Figure,text:impl Into<String>,x:f64,y:f64){let mut l=Label::new(text,x,y);l.color="#c2d5dd".into();f.labels.push(l);}
fn limits(name:&str,x:[f64;2],y:[f64;2])->([f64;2],[f64;2]){let v=fs::read_to_string("web/map-data/views.json").ok().and_then(|s|serde_json::from_str::<Value>(&s).ok());let Some(v)=v.and_then(|v|v.get(name).cloned())else{return(x,y)};let parse=|k:&str|->Option<[f64;2]>{let a=[v[k][0].as_f64()?,v[k][1].as_f64()?];(a.iter().all(|v|v.is_finite())&&a[1]>a[0]).then_some(a)};(parse("xlim").unwrap_or(x),parse("ylim").unwrap_or(y))}
fn custom_axes(name:&str,mut a:Axes)->Axes{let (x,y)=limits(name,a.xlim,a.ylim);a.xlim=x;a.ylim=y;a.xticks=(0..4).map(|i|x[0]+(x[1]-x[0])*i as f64/3.).collect();a.yticks=(0..5).map(|i|y[0]+(y[1]-y[0])*i as f64/4.).collect();if name=="structure"{
 a.xticks=((x[0].floor() as i32-1)..=(x[1].ceil() as i32+1)).flat_map(|k|[k as f64,k as f64+3f64.log10()]).filter(|v|*v>=x[0]&&*v<=x[1]).collect();
 if a.xticks.len()<2{a.xticks=vec![x[0],(x[0]+x[1])/2.,x[1]];}
 a.xticklabels=Some(a.xticks.iter().map(|v|{let t=10f64.powf(*v);if t>=1.{format!("{t:.0}")}else{format!("{t:.2}")}}).collect());
 let step=((y[1]-y[0])/5.).ceil().max(1.) as usize;
 a.yticks=((y[0].ceil() as i32)..=(y[1].floor() as i32)).step_by(step).map(|v|v as f64).collect();
 if a.yticks.len()<2{a.yticks=vec![y[0],(y[0]+y[1])/2.,y[1]];}
 a.yticklabels=Some(a.yticks.iter().map(|v|if v.fract().abs()<1e-9{format!("$10^{{{v:.0}}}$")}else{format!("$10^{{{v:.2}}}$")}).collect());
}else{a.xticklabels=Some(a.xticks.iter().map(|t|{let m=(*t/60.).round() as u64%1440;format!("{:02}:{:02}",m/60,m%60)}).collect());a.yticklabels=Some(a.yticks.iter().map(|v|format!("{v:.2}")).collect());}a}
fn save(f:&Figure,name:&str)->Result<()>{if let Some(p)=f.panels.first(){if let Some(a)=&p.axes{let points:Vec<[f64;2]>=p.layers.iter().filter_map(|l|if let Layer::Line(l)=l{["#8cebc2","#ac8dff"].contains(&l.color.as_str()).then_some(&l.points)}else{None}).flatten().filter(|p|p.iter().all(|v|v.is_finite())).copied().collect();let meta=serde_json::json!({"points":points,"xlim":a.xlim,"ylim":a.ylim,"rect":[p.rect.x/f.width_mm,p.rect.y/f.height_mm,p.rect.width/f.width_mm,p.rect.height/f.height_mm]});fs::write(format!("web/map-data/{name}.axes.tmp"),serde_json::to_vec(&meta)?)?;fs::rename(format!("web/map-data/{name}.axes.tmp"),format!("web/map-data/{name}.axes.json"))?;}}let mut sized=f.clone(); sized.width_mm*=0.6;sized.height_mm*=0.6;sized.font_pt=8.;for p in &mut sized.panels{p.rect.x*=0.6;p.rect.y*=0.6;p.rect.width*=0.6;p.rect.height*=0.6;}for l in &mut sized.labels{l.x*=0.6;l.y*=0.6;}let svg=sized.svg()?.replace("fill=\"white\"","fill=\"#101820\"").replace("#ffffff","#101820").replace("#fff\"","#101820\"").replace("#171717","#c2d5dd").replace("#444","#6f8791");let tmp=format!("web/map-data/{name}.tmp");fs::write(&tmp,svg)?;fs::rename(tmp,format!("web/map-data/{name}.svg"))?;Ok(())}
fn point(p:&Value)->Option<[f64;2]>{let a=[num(p,"lon"),num(p,"lat")];(a.iter().all(|v|v.is_finite())&&a[0].abs()<=180.&&a[1].abs()<=85.&&(a[0].abs()>1e-6||a[1].abs()>1e-6)).then_some(a)}
fn distance(a:[f64;2],b:[f64;2])->f64{let lat=((a[1]+b[1])*0.5).to_radians();111200.*((a[1]-b[1]).powi(2)+((a[0]-b[0])*lat.cos()).powi(2)).sqrt()}
fn coast(geom:&Value,paths:&mut Vec<Vec<[f64;2]>>){match geom["type"].as_str().unwrap_or(""){"Polygon"=>{for ring in geom["coordinates"].as_array().unwrap(){paths.push(ring.as_array().unwrap().iter().filter_map(|p|Some([p[0].as_f64()?,p[1].as_f64()?])).collect());}},"MultiPolygon"=>for poly in geom["coordinates"].as_array().unwrap(){coast(&serde_json::json!({"type":"Polygon","coordinates":poly}),paths)},"GeometryCollection"=>for g in geom["geometries"].as_array().unwrap(){coast(g,paths)},_=>{}}}
fn map(rows:&[Value],land:&Value,all:bool)->Result<(usize,usize)>{
 let mut good=vec![];let mut suspect=vec![];let mut last=std::collections::HashMap::<u64,(f64,[f64;2])>::new();
 // Bootstrap each track from a consistent pair, not a single corrupt float.
 for hz in [433500000u64,434000000]{let candidates:Vec<_>=rows.iter().filter(|p|p["hz"].as_u64()==Some(hz)).filter_map(|p|point(p).map(|x|(num(p,"utc"),x))).collect();for pair in candidates.windows(2){let dt=pair[1].0-pair[0].0;if dt>0.&&dt<60.&&distance(pair[0].1,pair[1].1)<500.+120.*dt{last.insert(hz,pair[0]);break;}}}
 for p in rows {if let Some(x)=point(p){let hz=p["hz"].as_u64().unwrap_or(0);let t=num(p,"utc");let plausible=last.get(&hz).is_none_or(|(pt,px)|distance(*px,x)<500.+120.*(t-pt).max(0.));if plausible{good.push((p,x));last.insert(hz,(t,x));}else{suspect.push((p,x));}}}
 let view:Vec<_>=if all{good.iter().chain(suspect.iter()).map(|(_,p)|*p).collect()}else{good.iter().map(|(_,p)|*p).collect()};
 let mut xmin=16.0f64;let mut xmax=16.1f64;let mut ymin=69.26f64;let mut ymax=69.35f64;
 if !view.is_empty(){xmin=view.iter().map(|p|p[0]).fold(f64::INFINITY,f64::min);xmax=view.iter().map(|p|p[0]).fold(f64::NEG_INFINITY,f64::max);ymin=view.iter().map(|p|p[1]).fold(f64::INFINITY,f64::min);ymax=view.iter().map(|p|p[1]).fold(f64::NEG_INFINITY,f64::max);}
 let cy=(ymin+ymax)*0.5;let cx=(xmin+xmax)*0.5;let c=cy.to_radians().cos().max(0.1);let dy=(ymax-ymin).max(0.045)*1.5;let dx=((xmax-xmin)*c).max(dy*1.7)*1.4;let yl=[cy-dy/2.,cy+dy/2.];let xl=[cx-dx/c/2.,cx+dx/c/2.];
 let (px,yl)=limits(if all{"map-all"}else{"map"},[xl[0]*c,xl[1]*c],yl);let xl=[px[0]/c,px[1]/c];let mut f=figure(160.,105.);let mut ax=Axes::new([xl[0]*c,xl[1]*c],yl,"Longitude (deg E)","Latitude (deg N)");ax.xticks=(0..4).map(|i|(xl[0]+(xl[1]-xl[0])*i as f64/3.)*c).collect();ax.xticklabels=Some(ax.xticks.iter().map(|v|format!("{:.3}",v/c)).collect());ax.yticks=(0..4).map(|i|yl[0]+(yl[1]-yl[0])*i as f64/3.).collect();ax.yticklabels=Some(ax.yticks.iter().map(|v|format!("{v:.3}")).collect());let mut panel=Panel::new(Rect::new(22.,8.,126.,78.),ax);
 let mut paths=vec![];for feature in land["features"].as_array().unwrap(){coast(&feature["geometry"],&mut paths)}
 let polygons:Vec<Vec<[f64;2]>>=paths.iter().filter(|path|path.iter().any(|p|p[0]>=xl[0]&&p[0]<=xl[1]&&p[1]>=yl[0]&&p[1]<=yl[1])).map(|path|path.iter().map(|p|[p[0]*c,p[1]]).collect()).collect();if !polygons.is_empty(){let values=vec![0.5;polygons.len()];let fill=f.scale(Scale::new([0.,1.],Normalization::Linear,ColorMap::new(vec![[0.13,0.23,0.24],[0.13,0.23,0.24]])?)?);panel.push(Layer::PolygonMesh(PolygonMesh::new(polygons,values,fill)?));}
 for path in paths{if !path.iter().any(|p|p[0]>=xl[0]&&p[0]<=xl[1]&&p[1]>=yl[0]&&p[1]<=yl[1]){continue;}let mut l=Line::new(path.into_iter().map(|p|[p[0]*c,p[1]]).collect(),"#607c82");l.width_pt=0.5;panel.push(Layer::Line(l));}
 for (hz,color,rgb) in [(433500000,"#8cebc2",[0.55,0.92,0.76]),(434000000,"#ac8dff",[0.67,0.55,1.])]{let pts:Vec<_>=good.iter().filter(|(p,_)|p["hz"].as_u64()==Some(hz)).map(|(_,p)|[p[0]*c,p[1]]).collect();let mut l=Line::new(pts.clone(),color);l.width_pt=0.8;panel.push(Layer::Line(l));panel.markers(&mut f,&pts,&MarkerStyle{shape:MarkerShape::Circle,size_pt:2.5,color:rgb})?;if let Some(p)=pts.last(){panel.markers(&mut f,&[*p],&MarkerStyle{shape:MarkerShape::Diamond,size_pt:7.,color:rgb})?;}}
 let bad:Vec<_>=suspect.iter().map(|(_,p)|[p[0]*c,p[1]]).collect();panel.markers(&mut f,&bad,&MarkerStyle{shape:MarkerShape::Circle,size_pt:2.,color:[1.,0.6,0.35]})?;
 f.panels.push(panel);save(&f,if all{"map-all"}else{"map"})?;Ok((good.len(),suspect.len()))
}
fn interp(x:f64,xs:&[Value],ys:&[Value])->f64{if x<=xs[0].as_f64().unwrap(){return ys[0].as_f64().unwrap();}for i in 1..xs.len(){let a=xs[i-1].as_f64().unwrap();let b=xs[i].as_f64().unwrap();if x<=b{let t=(x-a)/(b-a);return ys[i-1].as_f64().unwrap()*(1.-t)+ys[i].as_f64().unwrap()*t;}}ys.last().unwrap().as_f64().unwrap()}
fn pressure(rows:&[Value],profile:&Value)->Result<usize>{let valid:Vec<_>=rows.iter().filter(|p|{let v=num(p,"pressure_hpa");v>=0.1&&v<=1100.}).collect();if valid.is_empty(){let mut f=figure(160.,103.);f.panels.push(Panel::new(Rect::new(22.,9.,112.,74.),Axes::new([0.,60.],[0.,1.],"Time (UTC)","Pressure (hPa)")));label(&mut f,"No pressure data in this directory",45.,42.);save(&f,"pressure")?;return Ok(0);}let start=(num(valid[0],"utc")/900.).floor()*900.;let end=(num(valid.last().unwrap(),"utc")/900.).ceil()*900.;let end=end.max(start+900.);let mut f=figure(160.,103.);let rect=Rect::new(22.,9.,112.,74.);let minp=valid.iter().map(|p|num(p,"pressure_hpa")).fold(1100.,f64::min);let yl=[-1100f64.ln(),-(minp*0.8).max(0.1).ln()];let (xx,yl)=limits("pressure",[start,end],yl);let (start,end)=(xx[0],xx[1]);let mut ax=Axes::new([start,end],yl,"Time (UTC)","Pressure (hPa)");ax.xticks=(0..5).map(|i|start+(end-start)*i as f64/4.).collect();ax.xticklabels=Some(ax.xticks.iter().map(|t|{let m=(*t/60.).round() as u64%1440;format!("{:02}:{:02}",m/60,m%60)}).collect());ax.yticks=[1000f64,300.,100.,30.,10.,3.,1.].iter().map(|p|-p.ln()).collect();ax.yticklabels=Some(["1000","300","100","30","10","3","1"].iter().map(|s|s.to_string()).collect());ax.yticks=(0..5).map(|i|yl[0]+(yl[1]-yl[0])*i as f64/4.).collect();ax.yticklabels=Some(ax.yticks.iter().map(|v|format!("{:.1}",(-v).exp())).collect());let mut panel=Panel::new(rect,ax);
 for (hz,color,rgb) in [(433500000,"#8cebc2",[0.55,0.92,0.76]),(434000000,"#ac8dff",[0.67,0.55,1.])]{let points:Vec<_>=valid.iter().filter(|p|p["hz"].as_u64()==Some(hz)).map(|p|[num(p,"utc"),-num(p,"pressure_hpa").ln()]).collect();let mut l=Line::new(points.clone(),color);l.width_pt=0.5;panel.push(Layer::Line(l));panel.markers(&mut f,&points,&MarkerStyle{shape:MarkerShape::Circle,size_pt:1.8,color:rgb})?;}
 // The right axis uses p_MSIS(z) on precisely the same -ln(p) coordinate.
 let z=profile["z"].as_array().unwrap();let ps=profile["p"].as_array().unwrap();let mut axis=Line::new(vec![[end,yl[0]],[end,yl[1]]],"#6f8791");axis.width_pt=0.5;panel.push(Layer::Line(axis));
 for h in (0..=45).step_by(5){let ph=interp(h as f64,z,ps);let y=-ph.ln();if y>=yl[0]&&y<=yl[1]{let mm=rect.y+rect.height*(1.-(y-yl[0])/(yl[1]-yl[0]));label(&mut f,format!("{h}"),rect.x+rect.width+4.,mm);let mut tick=Line::new(vec![[end-(end-start)*0.012,y],[end,y]],"#6f8791");tick.width_pt=0.5;panel.push(Layer::Line(tick));}}
 let mut lab=Label::new("MSIS height estimate (km)",151.,46.);lab.rotation=-90.;lab.color="#c2d5dd".into();f.labels.push(lab);f.panels.push(panel);save(&f,"pressure")?;Ok(valid.len())}
fn time_axes(ts:&[f64],ylim:[f64;2],ylabel:&str)->Axes{let start=(ts[0]/900.).floor()*900.;let end=((ts[ts.len()-1]/900.).ceil()*900.).max(start+900.);let mut a=Axes::new([start,end],ylim,"Time (UTC)",ylabel);a.xticks=(0..4).map(|i|start+(end-start)*i as f64/3.).collect();a.xticklabels=Some(a.xticks.iter().map(|t|{let m=(*t/60.).round() as u64%1440;format!("{:02}:{:02}",m/60,m%60)}).collect());a}
fn diagnostics(a:&Value)->Result<(usize,usize)>{let channels=a["channels"].as_array().unwrap();let mut ts=vec![];let mut ys=vec![];for ch in channels{ts.extend(ch["prime_utc"].as_array().unwrap().iter().filter_map(Value::as_f64));ys.extend(ch["rho_prime_hpa"].as_array().unwrap().iter().filter_map(Value::as_f64));}ts.sort_by(f64::total_cmp);let count=ys.len();if ts.is_empty(){ts=vec![0.,60.];ys=vec![0.];}let bound=ys.iter().map(|v|v.abs()).fold(0.01,f64::max)*1.1;let mut f=figure(160.,103.);let mut panel=Panel::new(Rect::new(24.,8.,124.,73.),custom_axes("reynolds",time_axes(&ts,[-bound,bound],r"$\rho'$ [hPa]")));let mut zero=Line::new(vec![[ts[0],0.],[*ts.last().unwrap(),0.]],"#587079");zero.width_pt=0.4;panel.push(Layer::Line(zero));
 for ch in channels{let color=if ch["hz"].as_u64()==Some(433500000){"#8cebc2"}else{"#ac8dff"};let times=ch["prime_utc"].as_array().unwrap();let vals=ch["rho_prime_hpa"].as_array().unwrap();let mut pts=vec![];for i in 0..times.len(){let t=times[i].as_f64().unwrap();if i>0&&t-times[i-1].as_f64().unwrap()>20.{pts.push([f64::NAN;2]);}pts.push([t,vals[i].as_f64().unwrap()]);}let mut line=Line::new(pts,color);line.width_pt=0.7;panel.push(Layer::Line(line));}f.panels.push(panel);save(&f,"reynolds")?;
 let mut all=vec![];let mut lag=vec![];for ch in channels{for kind in ["raw_structure","prime_structure"]{let switches:Value=fs::read_to_string("web/map-data/views.json").ok().and_then(|s|serde_json::from_str(&s).ok()).unwrap_or(Value::Null);if switches[kind]==false{continue;}for v in ch[kind]["d2_hpa2"].as_array().unwrap(){let x=v.as_f64().unwrap();if x>0.{all.push(x.log10());}}for v in ch[kind]["lag_s"].as_array().unwrap(){lag.push(v.as_f64().unwrap().log10());}}}let mut f=figure(160.,103.);let ymin=all.iter().copied().fold(0.,f64::min).floor();let ymax=all.iter().copied().fold(1.,f64::max).ceil().max(ymin+1.);let mut ax=Axes::new([2f64.log10(),300f64.log10()],[ymin,ymax],r"Lag $\tau$ (s)",r"$D_2(\tau)$ [hPa$^2$]");ax.xticks=[3f64,10.,30.,100.,300.].iter().map(|x|x.log10()).collect();ax.xticklabels=Some(["3","10","30","100","300"].iter().map(|s|s.to_string()).collect());ax.yticks=(0..5).map(|i|ymin+(ymax-ymin)*i as f64/4.).collect();ax.yticklabels=Some(ax.yticks.iter().map(|x|format!("$10^{{{x:.1}}}$")).collect());let mut panel=Panel::new(Rect::new(24.,8.,124.,73.),custom_axes("structure",ax));
 for ch in channels{let color=if ch["hz"].as_u64()==Some(433500000){"#8cebc2"}else{"#ac8dff"};for kind in ["raw_structure","prime_structure"]{let switches:Value=fs::read_to_string("web/map-data/views.json").ok().and_then(|s|serde_json::from_str(&s).ok()).unwrap_or(Value::Null);if switches[kind]==false{continue;}let xs=ch[kind]["lag_s"].as_array().unwrap();let ys=ch[kind]["d2_hpa2"].as_array().unwrap();let points:Vec<[f64;2]>=xs.iter().zip(ys).filter_map(|(x,y)|{let (x,y)=(x.as_f64()?,y.as_f64()?);(y>0.).then_some([x.log10(),y.log10()])}).collect();let rgb=if ch["hz"].as_u64()==Some(433500000){[0.55,0.92,0.76]}else{[0.67,0.55,1.]};panel.markers(&mut f,&points,&MarkerStyle{shape:if kind=="raw_structure"{MarkerShape::Circle}else{MarkerShape::Diamond},size_pt:2.5,color:rgb})?;let fit=&ch[kind]["fit"];if let (Some(xx),Some(yy))=(fit["lag_s"].as_array(),fit["d2_hpa2"].as_array()){let pts=xx.iter().zip(yy).filter_map(|(x,y)|Some([x.as_f64()?.log10(),y.as_f64()?.log10()])).collect();let mut line=Line::new(pts,color);line.width_pt=1.;if kind=="prime_structure"{line.dash=Some("2 1".into());}panel.push(Layer::Line(line));}}}let mut entries=vec![LegendEntry::circle("Data (markers)","#c2d5dd")];
 let switches:Value=fs::read_to_string("web/map-data/views.json").ok().and_then(|s|serde_json::from_str(&s).ok()).unwrap_or(Value::Null);
 for ch in channels {let hz=ch["hz"].as_f64().unwrap_or(0.)/1e6;let color=if hz<434.{"#8cebc2"}else{"#ac8dff"};for kind in ["raw_structure","prime_structure"] {if switches[kind]==false{continue;}if let Some(beta)=ch[kind]["fit"]["exponent"].as_f64(){let rho=if kind=="raw_structure"{r"\rho"}else{r"\rho'"};entries.push(LegendEntry{label:format!(r"{hz:.3} MHz fit ${rho}\propto\tau^{{{beta:.2}}}$"),symbol:LegendSymbol::Line{color:color.into(),width_pt:1.5,dash:if kind=="prime_structure"{Some("2 1".into())}else{None}}});}}}
 let mut legend=Legend::new(entries);legend.position=LegendPosition::UpperLeft;legend.avoid_data=false;legend.background_opacity=0.94;legend.padding_mm=1.;panel.legend=Some(legend);f.panels.push(panel);save(&f,"structure")?;Ok((count,channels.iter().map(|c|c["removed"].as_u64().unwrap_or(0)as usize).sum()))}

fn main()->Result<()>{let mut d:Value=serde_json::from_str(&fs::read_to_string("web/map-data/history.json")?)?;let settings:Value=fs::read_to_string("web/map-data/views.json").ok().and_then(|s|serde_json::from_str(&s).ok()).unwrap_or(Value::Null);if let Some(visible)=settings["visible_hz"].as_array(){d["packets"].as_array_mut().unwrap().retain(|p|visible.contains(&p["hz"]));d["analysis"]["channels"].as_array_mut().unwrap().retain(|p|visible.contains(&p["hz"]));}let land:Value=serde_json::from_str(&fs::read_to_string("web/map-data/land.geojson")?)?;let rows=d["packets"].as_array().unwrap();let (gps,suspect)=map(rows,&land,false)?;map(rows,&land,true)?;let cleaned:Vec<Value>=d["analysis"]["channels"].as_array().unwrap().iter().flat_map(|c|c["utc"].as_array().unwrap().iter().zip(c["pressure_hpa"].as_array().unwrap()).map(move |(t,p)|serde_json::json!({"utc":t,"pressure_hpa":p,"hz":c["hz"]}))).collect();let mut cleaned=cleaned;cleaned.sort_by(|a,b|num(a,"utc").total_cmp(&num(b,"utc")));let count=pressure(&cleaned,&d["profile"])?;let (prime_points,pressure_removed)=diagnostics(&d["analysis"])?;let meta=serde_json::json!({"raw_structure":settings["raw_structure"],"prime_structure":settings["prime_structure"],"visible_hz":settings["visible_hz"],"data_dir":d["data_dir"],"generated_utc":d["generated_utc"],"packets":rows.len(),"gps_points":gps,"suspect_points":suspect,"pressure_points":count,"fits":d["analysis"]["channels"].as_array().unwrap().iter().map(|c|serde_json::json!({"hz":c["hz"],"raw":c["raw_structure"]["fit"],"prime":c["prime_structure"]["fit"]})).collect::<Vec<_>>(),"prime_points":prime_points,"pressure_removed":pressure_removed,"history_errors":d["history_errors"],"model":d["profile"]["model"],"assumptions":d["profile"]["assumptions"]});fs::write("web/map-data/meta.tmp",serde_json::to_vec(&meta)?)?;fs::rename("web/map-data/meta.tmp","web/map-data/meta.json")?;Ok(())}
